def ref(n): return {'$ref': '#/components/schemas/' + n}
def string(desc='', **kw): return dict(type='string', **({'description': desc} if desc else {}), **kw)
def enum(*v): return string(enum=list(v))
def num(desc='', **kw): return dict(type='number', description=desc, **kw)
def integer(desc='', **kw): return dict(type='integer', description=desc, **kw)
def arr(s): return {'type':'array', 'items': ref(s) if isinstance(s,str) else s}
def obj(props, required=()): return {'type':'object','properties':props, **({'required':list(required)} if required else {})}
def model(n,p,r=()): S[n]=obj(p,r); return ref(n)
