ERRORS={400:('BadRequest','Dữ liệu sai định dạng hoặc thiếu trường.','VALIDATION_ERROR'),401:('Unauthorized','Chưa xác thực hoặc thông tin xác thực hết hạn.','UNAUTHORIZED'),403:('Forbidden','Không đủ quyền, sai chủ sở hữu hoặc tài khoản bị khóa.','FORBIDDEN'),404:('NotFound','Không tìm thấy tài nguyên.','NOT_FOUND'),409:('Conflict','Xung đột trạng thái, phiên bản, dữ liệu trùng hoặc thao tác đã xử lý.','CONFLICT'),422:('Unprocessable','Dữ liệu đúng định dạng nhưng vi phạm điều kiện nghiệp vụ.','BUSINESS_RULE_VIOLATION'),429:('TooManyRequests','Vượt giới hạn yêu cầu/OTP. Thử lại theo Retry-After.','RATE_LIMITED'),500:('ServerError','Lỗi nội bộ; sử dụng requestId khi liên hệ hỗ trợ.','INTERNAL_ERROR'),503:('Unavailable','Dịch vụ phụ thuộc tạm không khả dụng.','SERVICE_UNAVAILABLE')}
RESP={}
for code,(name,desc,err) in ERRORS.items():
    RESP[name]={'description':desc,'content':{'application/json':{'schema':ref('Error'),'example':{'code':err,'message':desc,'requestId':'req_001'}}}}
RESP['TooManyRequests']['headers']={'Retry-After':{'description':'Thời gian chờ tính bằng giây.','schema':integer(minimum=1)}}
PATHS={}
def q(name,schema=None,required=False,description=''):
    return {'name':name,'in':'query','required':required,'description':description or name,'schema':schema or string()}
PAGE=[q('page',integer(minimum=1,default=1)),q('pageSize',integer(minimum=1,maximum=100,default=20))]
def paged(name):
    n=name+'Page'
    if n not in S: model(n,{'items':arr(name),'page':integer(minimum=1),'pageSize':integer(minimum=1,maximum=100),'total':integer(minimum=0)},['items','page','pageSize','total'])
    return n
def op(method,path,oid,title,tag,desc,response=None,body=None,status=200,roles=None,fr=(),uc=(),params=(),public=False,errors=(),idem=False):
    ps=[]
    import re
    for n in re.findall(r'\{([^}]+)\}',path): ps.append({'name':n,'in':'path','required':True,'description':'Mã định danh '+n,'schema':string(minLength=1),'example':n.replace('Id','_001')})
    ps+=list(params)
    if idem: ps.append({'$ref':'#/components/parameters/IdempotencyKey'})
    e={400,429,500}|set(errors)
    if not public: e|={401,403}
    if '{' in path: e.add(404)
    if method!='get': e|={409,422}
    responses={str(status):{'description': 'Xử lý thành công.' if status!=202 else 'Đã tiếp nhận; truy vấn tài nguyên trả về để theo dõi kết quả.'}}
    if response: responses[str(status)]['content']={'application/json':{'schema':ref(response)}}
    for c in sorted(e): responses[str(c)]={'$ref':'#/components/responses/'+ERRORS[c][0]}
    o={'tags':[tag],'summary':title,'operationId':oid,'description':desc,'responses':responses,'x-required-roles':roles or ['AUTHENTICATED'],'x-readme-fr':list(fr),'x-readme-use-cases':list(uc)}
    if ps:o['parameters']=ps
    if public:o['security']=[]; o['x-required-roles']=[]
    if body:o['requestBody']={'required':True,'content':{'application/json':{'schema':ref(body)}}}
    PATHS.setdefault(path,{})[method]=o
    return o

