op('post','/trips','createTrip','Tạo yêu cầu đặt xe','Trips','Kiểm tra estimateId thuộc khách, chưa hết hạn và khớp điểm đón/đến/loại xe. Tạo SEARCHING và UNPAID; tự động chọn tài xế AVAILABLE phù hợp, ưu tiên khoảng cách/hiệu quả, gửi offer. 201 chỉ xác nhận tạo yêu cầu. Không tìm được tài xế: chuyển CANCELLED với cancelCode=NO_DRIVER_AVAILABLE, cancelledBy=SYSTEM và thông báo. Thời gian và trọng số chưa chốt.', 'Trip','TripCreate',201,roles=['CUSTOMER'],fr=['FR02.4','FR03.1','FR03.2','FR03.3','FR03.6','FR03.7','FR07.1','FR07.6'],uc=['UC003','UC004'],idem=True)
op('get','/trips','listMyTrips','Lịch sử chuyến của tôi','Trips','Khách chỉ thấy chuyến của mình; tài xế chỉ thấy chuyến đã được phân công. Không cho client truyền customerId để xem người khác.',paged('Trip'),roles=['CUSTOMER','DRIVER'],params=PAGE+[q('status',ref('TripStatus'))],fr=['FR02.5'],uc=['UC009','UC012'])
op('get','/trips/{tripId}','getTrip','Chi tiết và trạng thái yêu cầu','Trips','Chỉ khách sở hữu hoặc tài xế được phân công. Thanh toán tách paymentStatus; COMPLETED không đồng nghĩa PAID.', 'Trip',roles=['CUSTOMER','DRIVER'],fr=['FR02.5','FR04.6'],uc=['UC009'])
op('get','/trips/{tripId}/tracking','trackTrip','Theo dõi vị trí và ETA','Trips','Polling snapshot có thời gian server. Chỉ khách sở hữu/tài xế được phân công. Giữ vị trí cuối khi mất GPS và trả STALE/UNAVAILABLE; không dùng vị trí cũ như dữ liệu trực tiếp. Sau kết thúc ngừng lộ vị trí mới của tài xế, chỉ trả vị trí cuối thuộc chuyến. Chu kỳ polling/ngưỡng stale chưa chốt.', 'Tracking',roles=['CUSTOMER','DRIVER'],fr=['FR04.6','FR04.7'],uc=['UC009'])
