op('post','/trips/{tripId}/status-transitions','transitionTrip','Cập nhật tiến trình/đồng bộ khi có mạng','Trips','Chỉ tài xế đang được phân công. Trình tự DRIVER_ASSIGNED → ARRIVED → PICKED_UP → IN_PROGRESS → COMPLETED. Nút Bắt đầu trong UC008 có thể gửi tuần tự PICKED_UP và IN_PROGRESS để lưu đủ FR04.3/FR04.4. ARRIVED kiểm tra GPS và ngưỡng khoảng cách chưa chốt (422 PICKUP_TOO_FAR). COMPLETED tự chốt cước từ dấu vết đã xác minh và gửi thông báo. Khi offline lưu request, gửi lại cùng Idempotency-Key; sai expectedVersion trả 409 VERSION_CONFLICT, đọc lại chuyến trước khi xử lý. Không chấp nhận thời gian tương lai hoặc trình tự sự kiện đảo ngược.', 'Trip','StatusChange',roles=['DRIVER'],fr=['FR04.2','FR04.3','FR04.4','FR04.5','FR05.1','FR05.2','FR07.3','FR07.4'],uc=['UC008'],idem=True)
op('post','/trips/{tripId}/cancel','cancelTrip','Hủy chuyến/hủy tìm kiếm/khách vắng mặt','Trips','Chỉ khách sở hữu hoặc tài xế được phân công. Thiết kế cho tự hủy ở SEARCHING, DRIVER_ASSIGNED, ARRIVED; đang chở khách cần vận hành xử lý sự cố. customerNoShow=true chỉ tài xế, trạng thái ARRIVED và hết thời gian chờ cấu hình. Ghi cancelCode/cancelledBy, thu hồi offer, giải phóng tài xế, gửi thông báo. Phí/chế tài hủy chưa chốt; không mặc định miễn phí.', 'Trip','CancelRequest',roles=['CUSTOMER','DRIVER'],fr=['FR07.7'],uc=['UC003','UC008','UC009'],idem=True)
op('get','/trips/{tripId}/fare','getFinalFare','Xem cước cuối và hóa đơn','Payments','Chỉ người tham gia chuyến. Cước được server tính khi kết thúc hoặc xử lý sự cố, chưa có trả 409 FARE_NOT_READY. Công thức chi tiết chưa chốt; client không gửi số tiền phải thu.', 'Fare',roles=['CUSTOMER','DRIVER'],fr=['FR05.1','FR05.2'],uc=['UC010'],errors=[409])
op('post','/trips/{tripId}/payments','createPayment','Khởi tạo thanh toán hoặc thanh toán lại','Payments','Chỉ khách sở hữu; chuyến đã có cước cuối. Lấy số tiền từ hóa đơn server. CASH tạo bản ghi PENDING chờ tài xế xác nhận; BANK_CARD/E_WALLET trả checkoutUrl mô phỏng. Chỉ tạo lần thử mới khi lần trước FAILED/CANCELLED; PENDING phải đối soát trước, PAID từ chối thu lại. Sau thất bại được đổi sang CASH theo chính sách. Timeout cổng giữ PENDING, tự truy vấn đối soát; không coi timeout là thất bại chắc chắn.', 'Payment','PaymentCreate',201,roles=['CUSTOMER'],fr=['FR06.1','FR06.2','FR06.5','FR06.6'],uc=['UC010','UC011'],idem=True,errors=[503])
