    if resource=='trips':params += [q('status',ref('TripStatus')),q('activeOnly',{'type':'boolean'}),q('driverId'),q('customerId')]
    op('get','/admin/'+resource,'adminList'+resource.title(),'Tra cứu '+resource,'Administration','Yêu cầu quyền '+resource+':read; lọc và phân trang trên toàn hệ thống. Dữ liệu cá nhân chỉ cho nhân viên có quyền nghiệp vụ tương ứng.',paged(name),roles=ADMIN,params=params,fr=[fr]+(['FR08.6'] if resource=='drivers' else []),uc=['UC013'] if resource!='trips' else ['UC014'])
    singular={'users':'user','drivers':'driver','vehicles':'vehicle','trips':'trip'}[resource]
